export const currentExamStatus='ยังไม่ยืนยันประกาศเฉพาะภาค 2/2569';
export function examEvidenceCard(code){const x=examEvidence[code];if(!x)return '';return `<section class="panel exam-evidence"><h2>หลักฐานรูปแบบข้อสอบ · ${code}</h2><p><b>${e(x.format)}ในหลักฐานย้อนหลัง</b> · ${e(x.period)}</p><p>${e(x.detail)}</p><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.publisher)} ↗</a><p class="notice">${currentExamStatus} · ไม่ใช้จำนวนข้อ เวลา หรือเงื่อนไขย้อนหลังเป็นข้อยืนยันของเทอมนี้</p></section>`;}
export function examEvidenceTable(){return `<section class="panel exam-evidence"><div class="section-heading"><div><h2>ตรวจรายวิชาและรูปแบบข้อสอบ 7 วิชา</h2><p>ภาค 2/2569 · 21 หน่วยกิต · ตรวจ 18 ต.ค. 2569</p></div><a class="button secondary" href="#documents/mr30-selected">ดู ม.ร.30 หน้า 142–143</a></div><p>รายวิชาอ้างอิงรายการลงทะเบียนที่คุณแจ้งและข้อมูลเดิม วันสอบตรวจเทียบไฟล์ ม.ร.30 แล้ว ไม่มีคาบชนกัน ส่วนรูปแบบข้อสอบใช้หลักฐานย้อนหลังแยกต่างหาก</p><div class="table-scroll"><table><thead><tr><th>วิชา / 3 หน่วยกิต</th><th>วันสอบ / คาบ</th><th>รูปแบบย้อนหลัง</th><th>หลักฐานและภาค</th></tr></thead><tbody>${courses.filter(c=>c.enrolled).map(c=>{const x=examEvidence[c.id];return `<tr><td><b>${c.id}</b><br>${e(c.title)}</td><td>${thaiDate(c.exam,true)}<br>คาบ ${c.slot}</td><td><span class="badge">${x.format}</span></td><td>${e(x.period)}<br><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.publisher)} ↗</a></td></tr>`;}).join('')}</tbody></table></div><p class="notice"><b>ทั้ง 7 วิชา: ${currentExamStatus}</b> — ม.ร.30 ยืนยันวันและคาบ แต่ไม่ระบุปรนัย/อัตนัย ตรวจประกาศผู้สอนอีกครั้ง และไม่เหมารวมว่าวิชา POL อื่นเป็นปรนัย</p></section>`;}
